import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"惜往日","description":"","frontmatter":{"title":"惜往日","date":"2026-11-24T00:00:00.000Z","seq":20,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"思美人","link":"/blogs/楚辞/思美人.html"},"next":{"text":"橘颂","link":"/blogs/楚辞/橘颂.html"}},"headers":[],"relativePath":"blogs/楚辞/惜往日.md","filePath":"blogs/楚辞/惜往日.md"}'),o={name:"blogs/楚辞/惜往日.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="惜往日" tabindex="-1">惜往日 <a class="header-anchor" href="#惜往日" aria-label="Permalink to &quot;惜往日&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　九章</p><div class="poem"><p class="poem-stanza">惜往日之曾信兮，受命诏以昭时。</p><p class="poem-stanza">奉先功以照下兮，明法度之嫌疑。</p><p class="poem-stanza">国富强而法立兮，属贞臣而日竢。</p><p class="poem-stanza">秘密事之载心兮，虽过失犹弗治。</p><p class="poem-stanza">心纯庞而不泄兮，遭谗人而嫉之。</p><p class="poem-stanza">君含怒而待臣兮，不清澈其然否。</p><p class="poem-stanza">蔽晦君之聪明兮，虚惑误又以欺。</p><p class="poem-stanza">弗参验以考实兮，远迁臣而弗思。</p><p class="poem-stanza">信谗谀之浑浊兮，盛气志而过之。</p><p class="poem-stanza">何贞臣之无罪兮，被离谤而见尤。</p><p class="poem-stanza">惭光景之诚信兮，身幽隐而备之。</p><p class="poem-stanza">临沅湘之玄渊兮，遂自忍而沉流。</p><p class="poem-stanza">卒没身而绝名兮，惜壅君之不昭。</p><p class="poem-stanza">君无度而弗察兮，使芳草为薮幽。</p><p class="poem-stanza">焉舒情而抽信兮，恬死亡而不聊。</p><p class="poem-stanza">独障壅而弊隐兮，使贞臣为无由。</p><p class="poem-stanza">闻百里之为虏兮，伊尹烹于庖厨。</p><p class="poem-stanza">吕望屠于朝歌兮，宁戚歌而饭牛。</p><p class="poem-stanza">不逢汤武与桓缪兮，世孰云而知之。</p><p class="poem-stanza">吴信谗而弗味兮，子胥死而后忧。</p><p class="poem-stanza">介子忠而立枯兮，文君寤而追求。</p><p class="poem-stanza">封介山而为之禁兮，报大德之优游。</p><p class="poem-stanza">思久故之亲身兮，因缟素而哭之。</p><p class="poem-stanza">或忠信而死节兮，或訑谩而不疑。</p><p class="poem-stanza">弗省察而按实兮，听谗人之虚辞。</p><p class="poem-stanza">芳与泽其杂糅兮，孰申旦而别之？</p><p class="poem-stanza">何芳草之早殀兮，微霜降而下戒。</p><p class="poem-stanza">谅聪不明而蔽壅兮，使谗谀而日得。</p><p class="poem-stanza">自前世之嫉贤兮，谓蕙若其不可佩。</p><p class="poem-stanza">妒佳冶之芬芳兮，嫫母姣而自好。</p><p class="poem-stanza">虽有西施之美容兮，谗妒入以自代。</p><p class="poem-stanza">愿陈情以白行兮，得罪过之不意。</p><p class="poem-stanza">情冤见之日明兮，如列宿之错置。</p><p class="poem-stanza">乘骐骥而驰骋兮，无辔衔而自载</p><p class="poem-stanza">乘泛泭以下流兮，无舟楫而自备。</p><p class="poem-stanza">背法度而心治兮，辟与此其无异。</p><p class="poem-stanza">宁溘死而流亡兮，恐祸殃之有再。</p><p class="poem-stanza">不毕辞而赴渊兮，惜壅君之不识。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
